def is_valid_python_identifier(s):
    reserved = {'if', 'else', 'elif', 'for', 'while', 'def', 'return', 'class', 'import', 'in',
                'not', 'and', 'or', 'True', 'False', 'None', 'break', 'continue', 'pass', 'try',
                'except', 'finally', 'with', 'as', 'lambda', 'yield'}
    if len(s) == 0:
        return False
    first = s[0]
    if not (first.isalpha() or first == '_'):
        return False
    for ch in s[1:]:
        if not (ch.isalnum() or ch == '_'):
            return False
    return s not in reserved

