def longest_common_prefix_case_insensitive(strs):
    if not strs:
        return ""
    first = strs[0]
    length = len(first)
    for s in strs[1:]:
        i = 0
        while i < length and i < len(s) and first[i].lower() == s[i].lower():
            i += 1
        length = min(length, i)
        if length == 0:
            break
    return first[:length]

