def is_valid_self_closing_mix(s):
    token_re = re.compile(r'<([a-z]+)/>|<([a-z]+)>|</([a-z]+)>')
    stack = []
    pos = 0
    while pos < len(s):
        m = token_re.match(s, pos)
        if not m:
            return False
        self_close, opening, closing = m.groups()
        if opening:
            stack.append(opening)
        elif closing:
            if not stack or stack.pop() != closing:
                return False
        pos = m.end()
    return not stack

